{
  "interpretation": {
    "name": "TightenForkliftF35OnLine3",
    "scope": {"line": 3, "station": "st3", "tool": "NR7", "variant": "F35"},
    "goal": "Obtain the F35 tightening program, bring nutrunner NR7 from the crib to station st3, tighten, evaluate and record the result, and return the tool to the crib.",
    "constraints": [
      "get-program is executed first, before any other operation",
      "NR7 is reserved before any tool-using step and released after it has been returned to the crib",
      "transport-tool is delegated to the executor agvexecutor",
      "NR7 is at st3 before configure-tool and tighten-fasteners are invoked",
      "The program (bolt count, torque, tolerance) comes only from get-program, with no literals in the Recipe",
      "The tightening is evaluated against its program and recorded for traceability",
      "The tool is returned to the crib after tightening"
    ],
    "preference": "",
    "priority": "normal",
    "horizon": "Single execution for the current request",
    "requested_capabilities": [],
    "omit_services": []
  },
  "recipe": {
    "name": "line3-nr7-tightening-f35",
    "first_action": "prepare",
    "actions": [
      {
        "name": "prepare",
        "next": "bring-tool",
        "steps": [
          {
            "name": "get-program-step",
            "service": "get-program",
            "next": ["reserve-tool-step"],
            "dep": [],
            "executor": null,
            "params": {}
          },
          {
            "name": "reserve-tool-step",
            "service": "reserve-tool",
            "next": [],
            "dep": [],
            "executor": null,
            "params": {}
          }
        ]
      },
      {
        "name": "bring-tool",
        "next": "tighten",
        "steps": [
          {
            "name": "transport-to-station-step",
            "service": "transport-tool",
            "next": [],
            "dep": ["reserve-tool-step"],
            "executor": "agvexecutor",
            "params": {"to": "station"}
          }
        ]
      },
      {
        "name": "tighten",
        "next": "quality",
        "steps": [
          {
            "name": "configure-tool-step",
            "service": "configure-tool",
            "next": ["tighten-fasteners-step"],
            "dep": ["get-program-step", "reserve-tool-step"],
            "executor": null,
            "params": {}
          },
          {
            "name": "tighten-fasteners-step",
            "service": "tighten-fasteners",
            "next": [],
            "dep": ["configure-tool-step", "reserve-tool-step"],
            "executor": null,
            "params": {}
          }
        ]
      },
      {
        "name": "quality",
        "next": "return-tool",
        "steps": [
          {
            "name": "evaluate-tightening-step",
            "service": "evaluate-tightening",
            "next": [],
            "dep": ["tighten-fasteners-step", "get-program-step"],
            "executor": null,
            "params": {}
          },
          {
            "name": "record-tightening-step",
            "service": "record-tightening",
            "next": [],
            "dep": ["tighten-fasteners-step"],
            "executor": null,
            "params": {}
          }
        ]
      },
      {
        "name": "return-tool",
        "next": null,
        "steps": [
          {
            "name": "transport-to-crib-step",
            "service": "transport-tool",
            "next": ["release-tool-step"],
            "dep": ["reserve-tool-step"],
            "executor": "agvexecutor",
            "params": {"to": "crib"}
          },
          {
            "name": "release-tool-step",
            "service": "release-tool",
            "next": [],
            "dep": ["reserve-tool-step"],
            "executor": null,
            "params": {}
          }
        ]
      }
    ]
  }
}
